import {Chess} from './vendor/chess.js';
import {LEVELS} from './game-core.js';
const values={p:100,n:320,b:330,r:500,q:900,k:0};
function score(c){if(c.isCheckmate())return -100000;if(c.isDraw())return 0;let n=0;for(const row of c.board())for(const p of row)if(p){const center=7-Math.abs(3.5-'abcdefgh'.indexOf(p.square[0]))-Math.abs(3.5-(+p.square[1]-1));n+=(p.color===c.turn()?1:-1)*(values[p.type]+(p.type==='p'?8*(p.color==='w'?+p.square[1]-2:7-+p.square[1])+5*(3.5-Math.abs(3.5-'abcdefgh'.indexOf(p.square[0]))):p.type==='k'?0:(p.type==='n'?10:6)*center));}return n}
export function chooseMove(fen,level=2,chosen=null,budgetOverride=null){const c=new Chess(fen),config=LEVELS[level]||LEVELS[2],deadline=Date.now()+(budgetOverride??config.budget);let nodes=0;const ordered=()=>c.moves({verbose:true}).sort((a,b)=>(values[b.captured]||0)-(values[a.captured]||0));function search(depth,alpha,beta){if((++nodes&63)===0&&Date.now()>deadline)throw Error('budget');if(!depth||c.isGameOver())return score(c);let best=-Infinity;for(const m of ordered()){c.move(m);let v;try{v=-search(depth-1,-beta,-alpha)}finally{c.undo()}best=Math.max(best,v);alpha=Math.max(alpha,v);if(alpha>=beta)break}return best}
const moves=ordered();if(!moves.length)return {move:null,depth:0,nodes};let ranked=moves.map(m=>({move:{from:m.from,to:m.to,promotion:m.promotion},san:m.san,score:0})),completed=0;for(let depth=1;depth<=config.depth;depth++){const round=[];try{for(const m of moves){c.move(m);let value;try{value=-search(depth-1,-Infinity,Infinity)}finally{c.undo()}round.push({move:{from:m.from,to:m.to,promotion:m.promotion},san:m.san,score:value});}ranked=round.sort((a,b)=>b.score-a.score);completed=depth;}catch{break}if(Date.now()>deadline)break}
// Easy may choose a near-best candidate; stronger levels always use their best completed search.
const pool=level===1?ranked.filter(r=>ranked[0].score-r.score<=80).slice(0,3):ranked.slice(0,1);const pick=chosen?ranked[0]:pool[Math.floor(Math.random()*pool.length)];const actual=chosen?ranked.find(r=>r.san===chosen):null;return {move:pick.move,san:pick.san,score:pick.score,depth:completed,nodes,best:ranked[0].san,loss:actual?Math.max(0,ranked[0].score-actual.score):null};}
